consultas_censo.comando:
SELECT SUM(QT_MAT_BAS) AS TOTAL_MATRICULAS
FROM matriculas
WHERE TP_DEPENDENCIA = 3 OR TP_DEPENDENCIA = 2;

SELECT DICIONARIO: IN_PODER_PUBLICO_PARCERIA
FROM matriculas
WHERE IN_PODER_PUBLICO_PARCERIA = 1;

SELECT NO_MUNICIPIO
FROM matriculas
WHERE QT_MAT_BAS = (SELECT MAX(QT_MAT_BAS) FROM matriculas);

SELECT SUM(QT_MAT_BAS) AS total_feminino, SUM(QT_MAT_BAS) AS total_masculino,
       (SUM(QT_MAT_BAS) - SUM(QT_MAT_BAS)) / SUM(QT_MAT_BAS) * 100 AS razao
FROM matriculas;

SELECT SUM(QT_MAT_BAS) AS total_matrículas, 
       SUM(QT_MAT_BAS * CASE WHEN QT_MAT_BAS > 180 THEN 1 ELSE 0 END) AS total_matrículas_18mais
FROM matriculas;

SELECT SUM(QT_MAT_BAS) AS total_matrículas_matutino
FROM matriculas
WHERE TP_LOCALIZACAO_DIFERENCIADA = 'MATUTINO' AND TP_CATEGORIA_ESCOLA_PRIVADA = 'DIURNA';

SELECT SUM(QT_MAT_BAS) AS total_matrículas_vespertino
FROM matriculas
WHERE TP_LOCALIZACAO_DIFERENCIADA = 'VESPERTINO' AND TP_CATEGORIA_ESCOLA_PRIVADA = 'DIURNA';
